const item = $input.first();

const url = item.json["Recording URL"];

const match = url.match(/\/d\/([^/]+)/);

if (!match) {
  throw new Error("Не вдалося отримати File ID із URL");
}

item.json.fileId = match[1];

return [item];

const items = $input.all();

// Якщо немає елементів
if (items.length === 0) {
  return [];
}

// Повертаємо тільки перший
return [items[0]];

const item = $input.first();

const words =
item.json.deepgramTranscription.results.channels[0].alternatives[0].words;

let dialogue = "";

let currentSpeaker = null;
let currentText = [];

for (const w of words) {

    if (currentSpeaker === null) {
        currentSpeaker = w.speaker;
    }

    if (w.speaker !== currentSpeaker) {

        dialogue +=
`${currentSpeaker === 0 ? "Менеджер" : "Клієнт"}:\n${currentText.join(" ")}\n\n`;

        currentText = [];
        currentSpeaker = w.speaker;
    }

    currentText.push(w.punctuated_word || w.word);
}

if (currentText.length) {
    dialogue +=
`${currentSpeaker === 0 ? "Менеджер" : "Клієнт"}:\n${currentText.join(" ")}`;
}

return [
{
    json:{
        row_number:item.json.row_number,
        fileId:item.json.fileId,
        dialogue
    }
}
];

const text = $input.first().json.output;

let formatted = text;

// Главный заголовок
formatted = "📞 *РАЗБОР ЗВОНКА*\n━━━━━━━━━━━━━━━━━━\n\n" + formatted;

// Красивые заголовки
const replacements = [
  [/##\s*СИЛЬНЫЕ СТОРОНЫ/gi, "🔥 *СИЛЬНЫЕ СТОРОНЫ*"],
  [/##\s*ЗОНЫ РОСТА/gi, "📌 *ЗОНЫ РОСТА*"],
  [/##\s*ЧТО МОЖНО БЫЛО СДЕЛАТЬ ЛУЧШЕ/gi, "💡 *ЧТО МОЖНО БЫЛО СДЕЛАТЬ ЛУЧШЕ*"],
  [/##\s*РЕКОМЕНДАЦИИ ДЛЯ TEAM LEAD/gi, "🎓 *РЕКОМЕНДАЦИИ ДЛЯ TEAM LEAD*"],
  [/##\s*РЕКОМЕНДАЦИИ ДЛЯ ТИМЛИДА/gi, "🎓 *РЕКОМЕНДАЦИИ ДЛЯ ТИМЛИДА*"],
];

for (const [regex, value] of replacements) {
    formatted = formatted.replace(regex, value);
}

// Маркированные списки
formatted = formatted.replace(/^\-\s/gm, "• ");

// Лишние пустые строки
formatted = formatted.replace(/\n{3,}/g, "\n\n");

// ---------------------------
// Разбиваем на сообщения
// ---------------------------

const LIMIT = 3800;
const result = [];

let current = "";

const paragraphs = formatted.split("\n\n");

for (const p of paragraphs) {

    if ((current + "\n\n" + p).length > LIMIT) {

        result.push({
            json: {
                telegram: current.trim()
            }
        });

        current = p;

    } else {

        current += (current ? "\n\n" : "") + p;

    }

}

if (current.trim()) {

    result.push({
        json: {
            telegram: current.trim()
        }
    });

}

return result;
